"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Maximize, Smartphone, QrCode, Copy } from "lucide-react"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"

function MouseIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 100 100"
      className={className}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      {/* 둥근 귀 */}
      <circle cx="25" cy="28" r="25" fill="currentColor" />
      <circle cx="75" cy="28" r="25" fill="currentColor" />
      <circle cx="25" cy="28" r="16" fill="#F9A8D4" />
      <circle cx="75" cy="28" r="16" fill="#F9A8D4" />

      {/* 통통한 얼굴 모양 (납작한 동그라미) */}
      <ellipse
        cx="50"
        cy="62"
        rx="42"
        ry="28"
        fill="currentColor"
      />

      {/* 발그레 볼 */}
      <ellipse cx="32" cy="65" rx="6" ry="4" fill="#F9A8D4" opacity="0.6" />
      <ellipse cx="68" cy="65" rx="6" ry="4" fill="#F9A8D4" opacity="0.6" />

      {/* 초롱초롱 눈 */}
      <circle cx="40" cy="56" r="4.5" fill="var(--background, #fff)" />
      <circle cx="60" cy="56" r="4.5" fill="var(--background, #fff)" />

      {/* 입 모양 w */}
      <path
        d="M45 64 Q 47.5 68 50 64 Q 52.5 68 55 64"
        stroke="var(--background, #fff)"
        strokeWidth="2.5"
        strokeLinecap="round"
        fill="none"
      />
    </svg>
  )
}

export default function HomePage() {
  const [networkIp, setNetworkIp] = useState<string>("localhost")
  const [isPublicUrl, setIsPublicUrl] = useState<boolean>(false)
  const [publicIp, setPublicIp] = useState<string>("")
  const [shareUrl, setShareUrl] = useState<string>("")
  const [isShareModalOpen, setIsShareModalOpen] = useState(false)

  useEffect(() => {
    fetch('/api/network-ip')
      .then(res => res.json())
      .then(data => {
        if (data.ip) {
          setNetworkIp(data.ip)
          setIsPublicUrl(data.isPublic || false)
          if (data.publicIp) setPublicIp(data.publicIp)
        }
      })
      .catch(console.error)
  }, [])

  const handleShareHome = () => {
    let mobileUrl = "";
    if (isPublicUrl) {
      mobileUrl = `${networkIp}/`
    } else {
      const port = window.location.port ? `:${window.location.port}` : ''
      mobileUrl = `http://${networkIp}${port}/`
    }
    
    setShareUrl(mobileUrl)
    setIsShareModalOpen(true)
  }

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl)
      alert("모바일용 링크가 복사되었습니다!\n카카오톡 등으로 스마트폰에 보내거나 QR 코드를 스캔하세요.")
    } catch {
      alert("복사에 실패했습니다.")
    }
  }

  return (
    <div className="mx-auto max-w-4xl px-4 py-8">
      {/* 헤더 */}
      <div className="mb-12 flex flex-col items-center text-center relative">
        <MouseIcon className="mb-4 h-20 w-20 text-primary" />
        <h1 className="mb-2 text-4xl font-bold tracking-tight text-foreground">
          웹툰 업로더
        </h1>
        <p className="text-lg text-muted-foreground mb-4">
          웹툰 썸네일 크기 확인 및 모바일 스크롤 테스트
        </p>

        <Button
          variant="secondary"
          size="sm"
          className="gap-2 shadow-md bg-white text-black hover:bg-zinc-100 mt-2"
          onClick={handleShareHome}
        >
          <QrCode className="h-4 w-4" />
          스마트폰으로 접속하기
        </Button>
      </div>

      {/* 카테고리 버튼 */}
      <div className="mb-12 grid gap-6 md:grid-cols-2">
        <Link href="/thumbnail-size" className="block">
          <Card className="group cursor-pointer border-border bg-card transition-all duration-300 hover:border-primary hover:shadow-lg hover:shadow-primary/10">
            <CardContent className="flex flex-col items-center gap-4 p-8">
              <div className="flex h-16 w-16 items-center justify-center rounded-full bg-primary/10 transition-colors group-hover:bg-primary/20">
                <Maximize className="h-8 w-8 text-primary" />
              </div>
              <div className="text-center">
                <h2 className="mb-2 text-xl font-semibold text-card-foreground">
                  사이트별 썸네일 크기 확인
                </h2>
                <p className="text-sm text-muted-foreground">
                  네이버, 봄툰, 레진 썸네일 미리보기
                </p>
              </div>
            </CardContent>
          </Card>
        </Link>

        <Link href="/mobile-scroll" className="block">
          <Card className="group cursor-pointer border-border bg-card transition-all duration-300 hover:border-primary hover:shadow-lg hover:shadow-primary/10">
            <CardContent className="flex flex-col items-center gap-4 p-8">
              <div className="flex h-16 w-16 items-center justify-center rounded-full bg-primary/10 transition-colors group-hover:bg-primary/20">
                <Smartphone className="h-8 w-8 text-primary" />
              </div>
              <div className="text-center">
                <h2 className="mb-2 text-lg lg:text-xl font-semibold text-card-foreground">
                  작품 스크롤 확인(모바일용)
                </h2>
                <p className="text-sm text-muted-foreground">
                  모바일 화면 스크롤 테스트
                </p>
              </div>
            </CardContent>
          </Card>
        </Link>
      </div>

      <Dialog open={isShareModalOpen} onOpenChange={setIsShareModalOpen}>
        <DialogContent className="sm:max-w-md flex flex-col items-center justify-center p-8">
          <DialogHeader className="w-full text-center">
            <DialogTitle className="text-xl">스마트폰으로 접속하기</DialogTitle>
            <DialogDescription>
              스마트폰 카메라로 QR 코드를 스캔하세요.
            </DialogDescription>
          </DialogHeader>

          <div className="my-6 rounded-xl bg-white p-4 shadow-sm border border-slate-100 flex justify-center w-full">
            {shareUrl ? (
              <img
                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(shareUrl)}`}
                alt="QR Code"
                width={200}
                height={200}
                className="rounded-lg object-contain w-[200px] h-[200px]"
              />
            ) : (
              <div className="w-[200px] h-[200px] bg-slate-100 rounded-lg animate-pulse" />
            )}
          </div>

          <p className="text-sm text-center text-muted-foreground w-full break-all mb-4 px-4 py-2 bg-secondary rounded-md">
            {shareUrl}
          </p>

          <div className="flex w-full gap-3 sm:flex-row flex-col justify-center">
            <Button onClick={copyToClipboard} variant="outline" className="gap-2">
              <Copy className="h-4 w-4" />
              링크 복사
            </Button>
            <Button onClick={() => setIsShareModalOpen(false)}>
              닫기
            </Button>
          </div>

          {publicIp && (
            <div className="mt-6 w-full rounded-lg bg-orange-50 p-4 text-sm text-orange-900 border border-orange-200">
              <span className="block font-bold mb-1 text-orange-950">⚠️ 초기 보안 화면 통과 방법</span>
              스마트폰 화면에 IP 입력칸이 나오면 아래의 IP(비밀번호)를 입력하고 <strong className="bg-orange-100 px-1 rounded">Submit</strong> 을 누르세요.
              <div className="mt-2 text-center text-lg font-mono font-bold tracking-widest text-orange-600 bg-white py-2 rounded border border-orange-100">
                {publicIp}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}
